{"command":"cat > /tmp/pty_seq.py << 'PY'
import os, pty, sys, time, select, json
cwd=sys.argv[1]; seq=json.loads(sys.argv[2]); args=sys.argv[3:]
pid,fd=pty.fork()
if pid==0:
    os.chdir(cwd); os.execv(args[0],args)
def drain():
    out=b""
    while True:
        r,_,_=select.select([fd],[],[],0.8)
        if not r: break
        try: d=os.read(fd,4096)
        except: break
        if not d: break
        out+=d
    txt=out.decode(errors='replace')
    # strip ansi for readability
    import re; txt=re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]','',txt)
    print(txt); print("---")
drain()
for s in seq:
    print(f">>> SEND {s!r}")
    b=s.encode().decode('unicode_escape').encode('latin1')
    os.write(fd,b); time.sleep(0.4); drain()
try: print("wait",os.waitpid(pid,os.WNOHANG))
except Exception as e: print(e)
PY
mkdir -p /tmp/gci10
timeout 10 python3 /tmp/pty_seq.py /tmp/gci10 '["x"]' /workspace/executable generate ci --output-path fresh.yml
timeout 10 python3 /tmp/pty_seq.py /tmp/gci10 '["\\u0003"]' /workspace/executable generate ci --output-path fresh2.yml"}

