def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if not len1 or not len2: return 0.0
    md=max(len1,len2)//2-1
    md=max(md,0)
    m1=[False]*len1; m2=[False]*len2; matches=0
    for i,c in enumerate(s1):
        lo=max(0,i-md); hi=min(i+md+1,len2)
        for j in range(lo,hi):
            if not m2[j] and s2[j]==c:
                m1[i]=True; m2[j]=True; matches+=1; break
    if not matches: return 0.0
    t=0; k=0
    for i in range(len1):
        if m1[i]:
            while not m2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (matches/len1+matches/len2+(matches-t)/matches)/3
def jw(a,b,p=0.1):
    j=jaro(a,b); prefix=0
    for x,y in zip(a,b):
        if x==y and prefix<4: prefix+=1
        else: break
    return j+prefix*p*(1-j)
