# ------------------------------------------------------------ clap emulation

def jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_distance = max(max(len1, len2)//2 - 1, 0)
    s1_matches = [False]*len1
    s2_matches = [False]*len2
    matches = 0
    for i in range(len1):
        lo = max(0, i - match_distance)
        hi = min(i + match_distance + 1, len2)
        for j in range(lo, hi):
            if not s2_matches[j] and s1[i] == s2[j]:
                s1_matches[i] = True
                s2_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    t = 0
    k = 0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]:
                k += 1
            if s1[i] != s2[k]:
                t += 1
            k += 1
    t //= 2
    return (matches/len1 + matches/len2 + (matches - t)/matches)/3.0

def did_you_mean_candidates(inp, candidates):
    scored = []
    for c in candidates:
        conf = jaro(inp, c)
        if conf > 0.7:
            scored.append((conf, c))
    # original sorts ascending by confidence (stable)
    scored.sort(key=lambda x: x[0])
    return scored

