def do_help(node_path, kind):
    _stdout_write(help_text(node_path, kind))
    raise ClapExit(0)

def do_version():
    _stdout_write(f"oranda {VERSION}\n")
    raise ClapExit(0)

def resolve_help_command(start_path, segs):
    """Execute a `help` subcommand. start_path is node where help was invoked ("" or "generate" etc)
    segs are tokens after `help`."""
    # special pseudo handling recursive
    # We walk using a helper that mirrors clap
    def rec(current_path, remaining):
        # current_path is a real command path or "help-pseudo:<parent>"
        if current_path.startswith("help-pseudo:"):
            parent = current_path.split(":",1)[1]
            if not remaining:
                _stdout_write(help_pseudo_text(parent))
                raise ClapExit(0)
            # any further segment is unrecognized for this pseudo command
            token = remaining[0]
            usage = f"{BIN_NAME} {parent+' ' if parent else ''}help [COMMAND]...".replace("  "," ")
            # root parent "" -> "executable help [COMMAND]..."
            if parent == "":
                usage = f"{BIN_NAME} help [COMMAND]..."
            else:
                usage = f"{BIN_NAME} {parent} help [COMMAND]..."
            clap_error(f"unrecognized subcommand '{token}'", usage=usage)
        # real command
        if not remaining:
            do_help(current_path if current_path else "root", "long")
            return
        token = remaining[0]
        cmd = CMDS.get(current_path)
        if cmd is None:
            # leaf help recursion on a leaf node: it has no subcommands, token is unrecognized
            # Determine usage from current path
            # cmd for leaf exists in CMDS (build etc)
            cmd = CMDS.get(current_path, CMDS[""])
        # if token is a subcommand of current
        sub = cmd.subcommands.get(token) if cmd else None
        if sub is not None:
            if sub == "help":
                # help pseudo under current
                if len(remaining) == 1:
                    _stdout_write(help_pseudo_text(current_path))
                    raise ClapExit(0)
                else:
                    rec(f"help-pseudo:{current_path}", remaining[1:])
                    return
            else:
                # move to child
                if len(remaining) == 1:
                    do_help(sub, "long")
                    return
                else:
                    rec(sub, remaining[1:])
                    return
        else:
            # unrecognized
            # if current is help-pseudo already handled
            _error_unrecognized_subcommand_for_help(cmd, token, current_path)
    rec(start_path, segs)

