        offset = max(0, min(offset, self.n))
        line_start = self.text.rfind("\n", 0, offset) + 1
        line = self.text.count("\n", 0, offset) + 1
        col = offset - line_start + 1
        return line, col
    def err(self, msg, offset):
        return SerdeJsonError(msg, offset)
    def skip_ws(self):
        while self.i < self.n and self.text[self.i] in " \t\n\r":
            self.i += 1
    def parse(self):
        self.skip_ws()
        if self.i >= self.n:
            # EOF while parsing a value
            if self.n == 0:
                raise SerdeJsonError("EOF while parsing a value", None)
            raise self.err("EOF while parsing a value", self.n-1)
        node = self.parse_value()
        self.skip_ws()
        if self.i < self.n:
            raise self.err("trailing characters", self.i)
        return node
    def parse_value(self):
        self.skip_ws()
        if self.i >= self.n:
            if self.n == 0:
                raise SerdeJsonError("EOF while parsing a value", None)
            raise self.err("EOF while parsing a value", self.n-1)
        ch = self.text[self.i]
        if ch == "{":
            return self.parse_object()
        if ch == "[":
            return self.parse_array()
        if ch == '"':
            s_node = self.parse_string()
            return s_node
        if ch == "-" or ch.isdigit():
            return self.parse_number()
        if ch == "t" or ch == "f" or ch == "n":
            return self.parse_literal()
        raise self.err("expected value", self.i)
    def parse_literal(self):
        start = self.i
        if self.text.startswith("true", start):
            lit = "true"
        elif self.text.startswith("false", start):
            lit = "false"
        elif self.text.startswith("null", start):
            lit = "null"
        else:
            # Determine expected literal by first char
            exp = {"t":"true","f":"false","n":"null"}[self.text[start]]
            # walk
            for k, ech in enumerate(exp):
                pos = start+k
                if pos >= self.n:
                    raise self.err("EOF while parsing a value", self.n-1)
                if self.text[pos] != ech:
                    raise self.err("expected ident", pos)
            lit = exp
        self.i = start + len(lit)
        if lit == "true":
            return JsonNode("bool", True, start, self.i)
        if lit == "false":
            return JsonNode("bool", False, start, self.i)
        return JsonNode("null", None, start, self.i)
    def parse_string(self):
        start = self.i
        self.i += 1  # opening quote
        out = []
        while True:
            if self.i >= self.n:
                raise self.err("EOF while parsing a string", self.n-1)
            ch = self.text[self.i]
            if ch == '"':
                self.i += 1
                return JsonNode("string", "".join(out), start, self.i)
            if ord(ch) < 0x20:
                raise self.err("control character (\\u0000-\\u001F) found while parsing a string", self.i)
            if ch == "\\":
                esc_pos = self.i
                self.i += 1
                if self.i >= self.n:
                    raise self.err("EOF while parsing a string", self.n-1)
                e = self.text[self.i]
                if e in '"\\/':
                    out.append(e); self.i += 1
                elif e == "b":
                    out.append("\b"); self.i += 1
                elif e == "f":
                    out.append("\f"); self.i += 1
                elif e == "n":
                    out.append("\n"); self.i += 1
                elif e == "r":
                    out.append("\r"); self.i += 1
                elif e == "t":
                    out.append("\t"); self.i += 1
                elif e == "u":
                    # 4 hex
                    hex_start = self.i+1
                    if hex_start+4 > self.n:
                        raise self.err("EOF while parsing a string", self.n-1)
                    hexpart = self.text[hex_start:hex_start+4]
                    if not all(c in "0123456789abcdefABCDEF" for c in hexpart):
                        # find first bad
                        for k,c in enumerate(hexpart):
                            if c not in "0123456789abcdefABCDEF":
                                raise self.err("invalid unicode code point", hex_start+k)
                    code = int(hexpart, 16)
                    self.i = hex_start+4
                    # surrogate pair
                    if 0xD800 <= code <= 0xDBFF and self.text[self.i:self.i+2] == "\\u":
                        hex2 = self.text[self.i+2:self.i+6]
                        if len(hex2)==4 and all(c in "0123456789abcdefABCDEF" for c in hex2):
                            code2 = int(hex2,16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                code = 0x10000 + ((code-0xD800)<<10) + (code2-0xDC00)
                                self.i += 6
                    out.append(chr(code))
                else:
                    raise self.err("invalid escape", self.i)
            else:
                out.append(ch); self.i += 1
    def parse_number(self):
        start = self.i
        if self.text[self.i] == "-":
            self.i += 1
            if self.i >= self.n:
                raise self.err("EOF while parsing a value", start)
            if not self.text[self.i].isdigit():
                raise self.err("invalid number", self.i)
        # int part
        if self.i < self.n and self.text[self.i] == "0":
            self.i += 1
            if self.i < self.n and self.text[self.i].isdigit():
                raise self.err("invalid number", self.i)
        elif self.i < self.n and self.text[self.i].isdigit():
            while self.i < self.n and self.text[self.i].isdigit():
                self.i += 1
        else:
            raise self.err("invalid number", self.i if self.i < self.n else start)
        is_float = False
        if self.i < self.n and self.text[self.i] == ".":
            is_float = True
            dot_pos = self.i
            self.i += 1
            if self.i >= self.n:
                raise self.err("EOF while parsing a value", dot_pos)
            if not self.text[self.i].isdigit():
                raise self.err("invalid number", self.i)
            while self.i < self.n and self.text[self.i].isdigit():
                self.i += 1
        if self.i < self.n and self.text[self.i] in "eE":
            is_float = True
            epos = self.i
            self.i += 1
            if self.i < self.n and self.text[self.i] in "+-":
                self.i += 1
            if self.i >= self.n:
                raise self.err("EOF while parsing a value", epos+ (1 if False else 0))
            if not self.text[self.i].isdigit():
                raise self.err("invalid number", self.i)
            while self.i < self.n and self.text[self.i].isdigit():
                self.i += 1
        raw = self.text[start:self.i]
        if is_float:
            try: val = float(raw)
            except: val = 0.0
            return JsonNode("float", val, start, self.i, raw=raw)
        else:
            try: val = int(raw)
            except: val = 0
            return JsonNode("int", val, start, self.i, raw=raw)
    def parse_object(self):
        start = self.i
        self.i += 1
        items = []
        self.skip_ws()
        if self.i >= self.n:
            raise self.err("EOF while parsing an object", start)
        if self.text[self.i] == "}":
            self.i += 1
            return JsonNode("object", None, start, self.i, items=items)
        while True:
            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing an object", start)
            if self.text[self.i] != '"':
                raise self.err("key must be a string", self.i)
            key_node = self.parse_string()
            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing an object", start)
            if self.text[self.i] != ":":
                raise self.err("expected `:`", self.i)
