            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing a value", self.n-1)
            val_node = self.parse_value()
            items.append((key_node.value, key_node, val_node))
            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing an object", start)
            ch = self.text[self.i]
            if ch == ",":
                self.i += 1
                continue
            if ch == "}":
                self.i += 1
                return JsonNode("object", None, start, self.i, items=items)
            raise self.err("expected `,` or `}`", self.i)
    def parse_array(self):
        start = self.i
        self.i += 1
        items = []
        self.skip_ws()
        if self.i >= self.n:
            raise self.err("EOF while parsing a list", start)
        if self.text[self.i] == "]":
            self.i += 1
            return JsonNode("array", None, start, self.i, items=items)
        while True:
            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing a list", start)
            val_node = self.parse_value()
            items.append(val_node)
            self.skip_ws()
            if self.i >= self.n:
                raise self.err("EOF while parsing a list", start)
            ch = self.text[self.i]
            if ch == ",":
                self.i += 1
                continue
            if ch == "]":
                self.i += 1
                return JsonNode("array", None, start, self.i, items=items)
            raise self.err("expected `,` or `]`", self.i)

def serde_line_col(text, offset):
    if offset is None:
        return 1,0
    # offset char index
    line_start = text.rfind("\n", 0, offset) + 1
    line = text.count("\n", 0, offset) + 1
    col = offset - line_start + 1
    return line, col

def node_type_desc(node):
    if node.kind == "int":
        return f"integer `{node.raw}`"
    if node.kind == "float":
        # serde prints Rust float: 1.5 etc. raw may be 1.0 - Rust Display for f64 gives "1.0"? serde error uses value.to_string?
        r = node.raw
        return f"floating point `{r}`"
    if node.kind == "bool":
        return f"boolean `{'true' if node.value else 'false'}`"
    if node.kind == "null":
        return "null"
    if node.kind == "string":
        return f'string "{node.value}"'
    if node.kind == "array":
        return "sequence"
    if node.kind == "object":
        return "map"
    return node.kind

