def expected_list_str(fields):
    # serde formatting for expected fields
    quoted = [f"`{f}`" for f in fields]
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return f"{quoted[0]} or {quoted[1]}"
    return "one of " + ", ".join(quoted)

