def validate_node(node, spec, text):
    """Returns python value or raises SerdeJsonError with msg and label offset."""
    # Null handling is done by caller for optional fields; here if spec expects something and node is null:
    # Structs etc will produce invalid type null
    if isinstance(spec, StrSpec):
        if node.kind == "string":
            return node.value
        # label: primitive end-1, seq/map opening
        if node.kind in ("array","object"):
            raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a string", node.start)
        raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a string", node.end-1)
    if isinstance(spec, BoolSpec):
        if node.kind == "bool":
            return node.value
        if node.kind in ("array","object"):
            raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a boolean", node.start)
        raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a boolean", node.end-1)
    if isinstance(spec, EnumSpec):
        if node.kind != "string":
            # enum deserialization expects a string identifier; serde gives "expected value" at start of value
            raise SerdeJsonError("expected value", node.start)
        if node.value not in spec.values:
            raise SerdeJsonError(f"unknown variant `{node.value}`, expected {expected_list_str(spec.values)}", node.end-1)
        return node.value
    if isinstance(spec, SeqSpec):
        if node.kind != "array":
            if node.kind in ("array","object"):
                raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a sequence", node.start)
            raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a sequence", node.end-1 if node.kind not in ("string",) else node.end-1)
            # string case: end-1 is closing quote? Earlier additional_css "x" column after quote, ok
        return [validate_node(item, spec.item, text) if not _is_optional(spec.item) else validate_optional(item, spec.item, text) for item in node.items]
    if isinstance(spec, MapSpec):
        if node.kind != "object":
            if node.kind in ("array","object"):
                # sequence for map: expected a map at opening
                if node.kind == "array":
                    raise SerdeJsonError(f"invalid type: sequence, expected a map", node.start)
                raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a map", node.start)
            raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected a map", node.end-1)
        out = {}
        for key, key_node, val_node in node.items:
            # duplicates in map? serde map will just overwrite? JSON object to IndexMap: duplicate keys -> last wins? For maps serde_json Map preserves...
            out[key] = validate_node(val_node, spec.val, text) if not _is_optional(spec.val) else validate_optional(val_node, spec.val, text)
        return out
    if isinstance(spec, StructSpec):
        return validate_struct(node, spec, text)
    if isinstance(spec, BoolOrSpec):
        # bool variant
        if node.kind == "bool":
            return node.value
        # else try struct
        try:
            result = validate_struct(node, spec.inner, text)
            return result
        except SerdeJsonError:
            # label at end of the whole value (end-1)
            raise SerdeJsonError("data did not match any variant of untagged enum BoolOr", node.end-1)
    if isinstance(spec, AnalyticsSpec):
        # externally tagged enum
        if node.kind != "object":
            raise SerdeJsonError("expected value", node.start)
        if len(node.items) == 0:
            raise SerdeJsonError("expected value", node.end-1)
        # first key
        key, key_node, val_node = node.items[0]
        variants = {"google": GoogleSpec, "plausible": PlausibleSpec, "fathom": FathomSpec, "umami": UmamiSpec}
        if key not in variants:
            raise SerdeJsonError(f"unknown variant `{key}`, expected {expected_list_str(list(variants.keys()))}", key_node.end-1)
        # if more than one key, serde expects end after first entry -> error "expected value" at (?) second key start?
        if len(node.items) > 1:
