        val = validate_struct(val_node, variants[key], text)
        return {key: val}
    raise Exception(f"unknown spec {spec}")

def _is_optional(spec):
    # our struct fields are all optional unless required flag used differently; Seq/Map items are not optional typically
    return False

def validate_optional(node, spec, text):
    if node.kind == "null":
        return None
    return validate_node(node, spec, text)

def validate_struct(node, spec, text):
    # struct from map
    if node.kind == "array":
        # seq form: need exactly len(fields)
        if len(node.items) != len(spec.fields):
            raise SerdeJsonError(f"invalid length {len(node.items)}, expected struct {spec.name} with {len(spec.fields)} elements", node.end-1)
        out = {}
        for (fname, fspec, required), item in zip(spec.fields, node.items):
            if item.kind == "null" and not required:
                out[fname] = None
            else:
                out[fname] = validate_node(item, fspec, text)
        return out
    if node.kind != "object":
        if node.kind in ("array","object"):
            raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected struct {spec.name}", node.start)
        raise SerdeJsonError(f"invalid type: {node_type_desc(node)}, expected struct {spec.name}", node.end-1)
    field_map = {f[0]: f for f in spec.fields}
    out = {fname: None for fname,_,_ in spec.fields}
    seen = set()
    for key, key_node, val_node in node.items:
        if key in seen and key in field_map:
            raise SerdeJsonError(f"duplicate field `{key}`", key_node.end-1)
        # duplicate for unknown? serde would error unknown first; handle below
        if key not in field_map:
            if spec.deny:
                fields = [f[0] for f in spec.fields]
                raise SerdeJsonError(f"unknown field `{key}`, expected {expected_list_str(fields)}", key_node.end-1)
            else:
                # ignore unknown, but still need to mark? unknown duplicates ignored
                continue
        seen.add(key)
        fname, fspec, required = field_map[key]
        if val_node.kind == "null" and not required:
            out[fname] = None
        else:
            # for required, null goes to validator which will invalid type null
            out[fname] = validate_node(val_node, fspec, text)
    # missing required
    for fname, fspec, required in spec.fields:
        if required and fname not in seen:
            raise SerdeJsonError(f"missing field `{fname}`", node.end-1)
        # also if required field was present but null? validate already errored
    return out

def parse_json_with_serde(text, spec, filename_display):
    """Parse and validate, raising OrandaError('failed to parse JSON') on failure."""
    try:
        parser = JsonParser(text)
        node = parser.parse()
        value = validate_node(node, spec, text) if not isinstance(spec, StructSpec) else validate_struct(node, spec, text)
        return value
    except SerdeJsonError as e:
        if e.label_offset is None:
            # empty source
            msg = f"{e.msg} at line 1 column 0"
            err = OrandaError("failed to parse JSON", causes=[msg], filename="", label_offset=None, source_text=text)
            # filename is empty string in json mode, no snippet
            err._empty_source = True
            raise err
        line, col = serde_line_col(text, e.label_offset)
        msg = f"{e.msg} at line {line} column {col}"
        # byte offset
        byte_offset = len(text[:e.label_offset].encode("utf-8")) if isinstance(text, str) else e.label_offset
        err = OrandaError("failed to parse JSON", causes=[msg], filename=filename_display, label_offset=e.label_offset, source_text=text)
        err._byte_offset = byte_offset
        raise err

