        if self.help_text:
            lines.extend(_wrap_simple(self.help_text, "  help: ", "        "))
        return "\n".join(lines) + "\n\n"
    if self.label_offset is not None:
        # temporarily temporarily convert label_offset to byte? render uses char offset for snippet - keeps char
        pass
    return _orig_render(self)
def _patched_json(self):
    obj = _orig_json(self)
    if getattr(self, "_empty_source", False):
        obj["diagnostic"]["filename"] = ""
        obj["diagnostic"]["labels"] = []
        return obj
    if hasattr(self, "_byte_offset"):
        # replace offset in labels
        if obj["diagnostic"].get("labels"):
            obj["diagnostic"]["labels"][0]["span"]["offset"] = self._byte_offset
    return obj
OrandaError.render = _patched_render
OrandaError.json_obj = _patched_json

