# ---------------------------------------------------------- config loading

class LoadedConfig:
    def __init__(self, layer=None, path_display=None, config_dir=None):
        self.layer = layer  # validated dict or None
        self.path_display = path_display
    def section(self, name):
        if not self.layer: return None
        v = self.layer.get(name)
        return v
    def project(self):
        v = self.section("project")
        return v if isinstance(v, dict) else {}
    def build_cfg(self):
        v = self.section("build")
        return v if isinstance(v, dict) else {}
    def styles(self):
        v = self.section("styles")
        return v if isinstance(v, dict) else {}
    def components(self):
        v = self.section("components")
        return v if isinstance(v, dict) else {}
    def marketing(self):
        v = self.section("marketing")
        return v if isinstance(v, dict) else {}
    def workspace(self):
        v = self.section("workspace")
        return v if isinstance(v, dict) else {}

def load_config(config_path_arg):
    # returns LoadedConfig or raises OrandaError for parse errors
    if config_path_arg is not None:
        candidate = config_path_arg
        display = config_path_arg
    else:
        candidate = "./oranda.json"
        display = "./oranda.json"
    try:
        with open(candidate, "rb") as f:
            data = f.read()
    except OSError:
        debug("No config found, using default values")
        return LoadedConfig(None)
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        debug("No config found, using default values")
        return LoadedConfig(None)
    # parse (may raise)
    layer = parse_json_with_serde(text, OrandaSpec, display)
    return LoadedConfig(layer, path_display=display)

# ---------------------------------------------------- manifest detection

def cargo_warning_render(abs_path, kind, cargo_stderr=None, spawn_err=None):
    lines = []
    top = f"We found a potential rust project at {abs_path} but there was an issue"
    lines.extend(_wrap_simple(top, "  \u26a0 ", "  \u2502 "))
    if kind == "spawn":
        osmsg = os_error_str(spawn_err)
        lines.append("  \u251c\u2500\u25b6   \u00d7 `cargo metadata` execution failed")
        lines.append("  \u2502   ")
        lines.extend(_wrap_simple(f"failed to start `cargo metadata`: {osmsg}", "  \u251c\u2500\u25b6 ", "  \u2502   "))
        lines.extend(_wrap_simple(osmsg, "  \u2570\u2500\u25b6 ", "      "))
    else:
        cause = "`cargo metadata` exited with an error: " + (cargo_stderr or "")
        lines.append("  \u251c\u2500\u25b6   \u00d7 `cargo metadata` execution failed")
        lines.append("  \u2502   ")
        # render cause manually: first line prefix, rest continuation, preserving physical lines
        physical = cause.split("\n")
        # wrap first physical? cargo lines are short; use wrap for first line then verbatim rest
        first_wrapped = _wrap_simple(physical[0], "  \u2570\u2500\u25b6 ", "      ")
        lines.extend(first_wrapped)
        for extra in physical[1:]:
            lines.append("      " + extra if extra else "      ")
        # if cause does not end with newline, textwrap semantics? cargo stderr usually ends with newline
        # physical split already yields trailing "" if ends with \n -> included as "      "
    return "\n".join(lines) + "\n\n"

def js_warning_render(abs_path, nested):
    """nested is OrandaError or a special tuple"""
    top = f"We found a potential javascript project at {abs_path} but there was an issue"
    lines = []
    lines.extend(_wrap_simple(top, "  \u26a0 ", "  \u2502 "))
    if isinstance(nested, tuple) and nested[0] == "no_name":
        lines.append(f"  \u2570\u2500\u25b6   \u00d7 your package doesn't have a name: {abs_path}")
        lines.append("        help: is it a workspace? We don't support that yet.")
        lines.append("      ")
        return "\n".join(lines) + "\n\n"
    # nested OrandaError
    has_causes = bool(nested.causes)
    connector = "  \u251c\u2500\u25b6 " if has_causes else "  \u2570\u2500\u25b6 "
    cont = "  \u2502   " if has_causes else "      "
    # message may be wrapped in nested; approximate single line
    lines.extend(_wrap_simple(nested.message, connector + "  \u00d7 ", cont + "  \u2502 "))
    # internal lines: snippet and/or help
    if getattr(nested, "_empty_source", False):
        pass
    elif nested.label_offset is not None and nested.source_text is not None:
        snippet = nested._snippet()
        for s in snippet:
            lines.append(cont + s)
    if nested.help_text:
