        raise _js_serde_error(text, f"invalid type: {node_type_desc(node)}, expected struct PackageJson", node.end-1 if node.kind not in ("array","object") else node.start)
    result = {"name": None, "version": None, "description": None, "homepage": None, "license": None, "repository": None}
    seen = set()
    for key, key_node, val_node in node.items:
        if key not in result and key not in ("repository",):
            continue
        if key == "name" or key in ("description","homepage","license"):
            if val_node.kind == "null":
                result[key] = None
            elif val_node.kind != "string":
                raise _js_serde_error(text, f"invalid type: {node_type_desc(val_node)}, expected a string", val_node.end-1 if val_node.kind not in ("array","object") else val_node.start)
            else:
                result[key] = val_node.value
        elif key == "version":
            if val_node.kind == "null":
                result[key] = None
            elif val_node.kind != "string":
                raise _js_serde_error(text, f"invalid type: {node_type_desc(val_node)}, expected a version string", val_node.end-1 if val_node.kind not in ("array","object") else val_node.start)
            else:
                try:
                    result[key] = parse_js_version_value(val_node)
                except SerdeJsonError as e:
                    raise _js_serde_error(text, e.msg, e.label_offset)
        elif key == "repository":
            if val_node.kind == "null":
                result[key] = None
            elif val_node.kind == "string":
                result[key] = ("string", val_node.value)
            elif val_node.kind == "object":
                url = None; typ = None
                ok = True
                for k,k_node,v_node in val_node.items:
                    if k == "url":
                        if v_node.kind == "string": url = v_node.value
                        elif v_node.kind == "null": url = None
                        else: ok = False
                    elif k == "type":
                        if v_node.kind == "string": typ = v_node.value
                        elif v_node.kind == "null": typ = None
                        else: ok = False
                    else:
                        continue
                if not ok:
                    raise _js_serde_error(text, "data did not match any variant of untagged enum Repository", val_node.end-1)
                result[key] = ("object", url, typ)
            else:
                raise _js_serde_error(text, "data did not match any variant of untagged enum Repository", val_node.end-1)
    return result

def _js_serde_error(text, msg, offset):
    if offset is None:
        err = OrandaError("failed to parse JSON", causes=[f"{msg} at line 1 column 0"], filename="", label_offset=None, source_text=text); err._empty_source=True; return err
    line,col = serde_line_col(text, offset)
    err = OrandaError("failed to parse JSON", causes=[f"{msg} at line {line} column {col}"], filename=None, label_offset=offset, source_text=text)
    err._byte_offset = len(text[:offset].encode())
    return err

