# ------------------------------------------------------------- network fetching

class FetchFailure(Exception):
    def __init__(self, url, summary, causes):
        self.url = url
        self.summary = summary  # e.g. "error trying to connect: dns error: ..."
        self.causes = causes    # list starting with "error sending request ..."

DNS_PHRASES = {
    -2: "Name or service not known",
    -3: "Temporary failure in name resolution",
    -5: "No address associated with hostname",
    -11: "Resource temporarily unavailable",
    -4: "Non-recoverable failure in name resolution",
    11001: "No such host is known",
}

def _dns_message():
    return "failed to lookup address information: Temporary failure in name resolution"

def fetch_url_bytes(url, timeout=20):
    """Attempt a real fetch. Raises FetchFailure with reqwest-like causes."""
    # Try DNS first to emulate reqwest DNS errors deterministically offline
    parsed = urllib.parse.urlparse(url)
    host = parsed.hostname
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    if host:
        try:
            socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
        except socket.gaierror as e:
            err_no = e.errno if e.errno is not None else -3
            phrase = DNS_PHRASES.get(err_no, e.strerror or "Temporary failure in name resolution")
            dns_msg = f"failed to lookup address information: {phrase}"
            summary = f"error trying to connect: dns error: {dns_msg}"
            causes = [
                f"error sending request for url ({url}): {summary}",
                summary,
                f"dns error: {dns_msg}",
                dns_msg,
            ]
            raise FetchFailure(url, summary, causes)
        except Exception:
            pass
    req = urllib.request.Request(url, headers={"User-Agent": "oranda"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.read()
    except urllib.error.HTTPError as e:
        # reqwest would not necessarily error for status; return body for caller to interpret
        try:
            return e.read()
        except Exception:
            raise FetchFailure(url, "error trying to connect", [f"error sending request for url ({url}): error trying to connect", "error trying to connect"])
    except Exception as e:
        # Generic connection error
        msg = str(e)
        summary = f"error trying to connect: {msg}"
        raise FetchFailure(url, summary, [f"error sending request for url ({url}): {summary}", summary])

def fetch_with_proxy(proxy_url, direct_url):
    """Returns bytes from proxy or direct, printing proxy fallback notice on proxy failure.
    Raises FetchFailure for direct failure."""
    try:
        return fetch_url_bytes(proxy_url)
    except FetchFailure as e:
        # e.causes[0] is "error sending request for url (proxy): ..."
        _stdout_write("Fetching from proxy encountered an error:\n")
        _stdout_write(f" {e.causes[0]}.\n")
        _stdout_write(" Falling back to GitHub directly...\n")
    return fetch_url_bytes(direct_url)

def remote_asset_error(url, include_duplicate=True):
    try:
        fetch_url_bytes(url)
        return None
    except FetchFailure as e:
        return e

def load_local_asset_bytes(path_display):
    try:
        with open(path_display, "rb") as f:
            return f.read()
    except OSError as e:
        raise OrandaError(f"failed to read asset from {path_display}", causes=[os_error_str(e)], help_text="Make sure your path is relative to your oranda config or project manifest file.")

def load_remote_or_local_asset(path_display, duplicate_cause=True):
    if path_display.startswith("http://") or path_display.startswith("https://"):
        try:
            return fetch_url_bytes(path_display)
        except FetchFailure as e:
            msg = f"failed to fetch asset at {path_display}: Encountered an error when requesting a remote asset."
            if duplicate_cause:
                causes = [msg] + e.causes
            else:
                causes = e.causes
            raise OrandaError(msg, causes=causes, help_text="Make sure the url you provided is accurate.")
    else:
        return load_local_asset_bytes(path_display)

def write_asset_file(dest_path_display, data_bytes):
    # dest_path_display is a filesystem path string as displayed in errors
    try:
        parent = os.path.dirname(dest_path_display)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(dest_path_display, "wb") as f:
            f.write(data_bytes)
    except OSError as e:
        # determine if filename missing
        raise OrandaError(f"failed to write a new asset to {dest_path_display}.", causes=[os_error_str(e)], help_text="Make sure you have the correct permissions to create a new file.")

def parse_github_repo(s):
    if s is None:
        return None
    if s.startswith("git@github.com:"):
        rest = s[len("git@github.com:"):]
        # strip trailing spaces? observed trailing space succeeds for https; for scp assume strip
        rest = rest.rstrip()
        if rest.endswith("/"):
            rest = rest[:-1]
        segs = [seg for seg in rest.split("/") if seg != ""]
        # Actually "/extra" case should fail: need count of non-empty segments as in raw split including empties at ends ignored
        raw_segs = rest.split("/")
        # Count segments ignoring leading/trailing empty
        if len(segs) != 2:
            return None
        owner, repo = segs
        if repo.endswith(".git"):
            repo = repo[:-4]
        return (owner, repo)
    url_str = None
    if s.startswith("git+"):
        rest = s[4:]
        if not rest.startswith("https://"):
            return None
        url_str = rest
    elif s.startswith("https://"):
        url_str = s
    else:
        return None
    url_str = url_str.rstrip()
    # urlparse requires no spaces; remove fragments etc via parsing
    try:
        parsed = urllib.parse.urlparse(url_str)
    except Exception:
        return None
    if parsed.hostname is None or parsed.hostname.lower() != "github.com":
        return None
    segs = [seg for seg in parsed.path.split("/") if seg != ""]
    if len(segs) != 2:
        return None
    owner, repo = segs
    # url decode? GitHub owner/repo are plain
    owner = urllib.parse.unquote(owner); repo = urllib.parse.unquote(repo)
    if repo.endswith(".git"):
        repo = repo[:-4]
    return (owner, repo)

PY"}

