    ("aarch64-apple-darwin","macOS Apple Silicon"),
    ("x86_64-apple-darwin","macOS Intel"),
    ("x86_64-pc-windows-msvc","Windows x64"),
    ("x86_64-unknown-linux-gnu","Linux x64"),
]

class SiteContext:
    pass

def bool_or_layer(val):
    # returns (is_bool_false, layer_dict_or_empty, raw)
    if val is False:
        return True, {}, val
    if isinstance(val, dict):
        return False, val, val
    # True or None
    return False, {}, val

def get_nested(d, *keys):
    cur = d
    for k in keys:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(k)
    return cur

def build_context(config_path_arg, json_only=False):
    ctx = SiteContext()
    ctx.cwd = os.getcwd()
    ctx.config = load_config(config_path_arg)  # may raise
    layer = ctx.config.layer or {}
    proj_cfg = ctx.config.project()
    # detect manifest (only if not ??? serve uses a different path)
    manifest = detect_project(ctx.cwd)
    ctx.manifest = manifest
    # merge project
    def pick(cfg_val, man_val, default=None):
        return cfg_val if cfg_val is not None else (man_val if man_val is not None else default)
    ctx.project_name = pick(proj_cfg.get("name"), manifest.name, "My Oranda Project")
    ctx.project_version = pick(proj_cfg.get("version"), manifest.version, None)
    ctx.description = pick(proj_cfg.get("description"), manifest.description, None)
    ctx.homepage = pick(proj_cfg.get("homepage"), manifest.homepage, None)
    ctx.repository = pick(proj_cfg.get("repository"), manifest.repository, None)
    ctx.license = pick(proj_cfg.get("license"), manifest.license, None)
    ctx.readme_path_cfg = pick(proj_cfg.get("readme_path"), manifest.readme_path, "README.md")
    build_cfg = ctx.config.build_cfg()
    ctx.dist_dir = build_cfg.get("dist_dir") if build_cfg.get("dist_dir") is not None else "public"
    ctx.static_dir = build_cfg.get("static_dir") if build_cfg.get("static_dir") is not None else "static"
    ctx.path_prefix = build_cfg.get("path_prefix")  # may be None
    ctx.additional_pages = build_cfg.get("additional_pages")  # ordered dict or None
    styles = ctx.config.styles()
    ctx.theme_name = styles.get("theme") if styles.get("theme") is not None else "dark"
    ctx.theme_class = {"light":"light","dark":"dark","axolight":"axo","axodark":"dark axo","hacker":"hacker","cupcake":"cupcake"}.get(ctx.theme_name, "dark")
    ctx.logo_path = styles.get("logo")
    ctx.favicon_path = styles.get("favicon")
    ctx.additional_css = styles.get("additional_css")  # list or None
    ctx.oranda_css_version = styles.get("oranda_css_version") if styles.get("oranda_css_version") is not None else VERSION_CSS
    ctx.syntax_theme = styles.get("syntax_theme")
    marketing = ctx.config.marketing()
    ctx.analytics = marketing.get("analytics") if isinstance(marketing.get("analytics"), dict) else None
    ctx.social = marketing.get("social") if isinstance(marketing.get("social"), dict) else {}
    if not isinstance(ctx.social, dict): ctx.social = {}
    comps = ctx.config.components()
    ctx.source_cfg = comps.get("source")  # github/axodotdev/None
    # components resolution
    # changelog
    ch_val = comps.get("changelog") if "changelog" in (ctx.config.components() or {}) or comps else None
    # Note components() returns {} if absent; use raw layer presence
    raw_comps = ctx.config.layer.get("components") if ctx.config.layer and isinstance(ctx.config.layer.get("components"), dict) else {}
    if raw_comps is None: raw_comps = {}
    ctx.raw_components = raw_comps
    ch_raw = raw_comps.get("changelog")
    ctx.changelog_enabled = not (ch_raw is False)
    ch_layer = ch_raw if isinstance(ch_raw, dict) else {}
    ctx.changelog_rss = True
    ctx.read_changelog_file = True
    if isinstance(ch_raw, dict):
        if ch_raw.get("rss_feed") is not None:
            ctx.changelog_rss = bool(ch_raw.get("rss_feed"))
        if ch_raw.get("read_changelog_file") is not None:
            ctx.read_changelog_file = bool(ch_raw.get("read_changelog_file"))
    # artifacts
    art_raw = raw_comps.get("artifacts")
    ctx.artifacts_enabled = False
    ctx.artifacts_layer = {}
    ctx.package_managers_preferred = {}
    ctx.package_managers_additional = {}
    if not (art_raw is False):
        if isinstance(art_raw, dict):
            ctx.artifacts_layer = art_raw
        pm = ctx.artifacts_layer.get("package_managers") if isinstance(ctx.artifacts_layer, dict) else None
        if isinstance(pm, dict):
            if isinstance(pm.get("preferred"), dict):
                ctx.package_managers_preferred = pm.get("preferred")
            if isinstance(pm.get("additional"), dict):
                ctx.package_managers_additional = pm.get("additional")
        has_pm = bool(ctx.package_managers_preferred or ctx.package_managers_additional)
        cargo_dist_cfg = ctx.artifacts_layer.get("cargo_dist") if isinstance(ctx.artifacts_layer, dict) else None
        if cargo_dist_cfg is not None:
            cargo_dist_enabled = bool(cargo_dist_cfg)
        else:
            cargo_dist_enabled = bool(manifest.cargo_dist)
        auto_cfg = ctx.artifacts_layer.get("auto") if isinstance(ctx.artifacts_layer, dict) else None
        auto_enabled = bool(auto_cfg) if auto_cfg is not None else False
        ctx.cargo_dist_enabled = cargo_dist_enabled
        if has_pm or cargo_dist_enabled or auto_enabled:
            ctx.artifacts_enabled = True
    else:
        ctx.cargo_dist_enabled = False
    # funding
    fund_raw = raw_comps.get("funding")
    ctx.funding_enabled = False
    ctx.funding_layer = {}
    if not (fund_raw is False):
        if isinstance(fund_raw, dict):
            ctx.funding_layer = fund_raw
            if any(v is not None for v in fund_raw.values()):
                ctx.funding_enabled = True
        if not ctx.funding_enabled:
            if os.path.exists("funding.md") or os.path.exists(os.path.join(".github","FUNDING.yml")):
                ctx.funding_enabled = True
                if isinstance(fund_raw, dict):
                    ctx.funding_layer = fund_raw
    # mdbook
    md_raw = raw_comps.get("mdbook")
    ctx.mdbook_enabled = False
    ctx.mdbook_layer = {}
    if not (md_raw is False):
        if isinstance(md_raw, dict):
            ctx.mdbook_layer = md_raw
            if any(v is not None for v in md_raw.values()):
                ctx.mdbook_enabled = True
        if not ctx.mdbook_enabled:
            for cand in [".", "book", "docs"]:
                if os.path.isfile(os.path.join(cand, "book.toml")):
                    ctx.mdbook_enabled = True
                    break
            if isinstance(md_raw, dict) and not ctx.mdbook_layer:
                ctx.mdbook_layer = md_raw
    ctx.components_list = []
    if ctx.artifacts_enabled: ctx.components_list.append("artifacts")
    if ctx.changelog_enabled: ctx.components_list.append("changelog")
    if ctx.funding_enabled: ctx.components_list.append("funding")
    if ctx.mdbook_enabled: ctx.components_list.append("mdbook")
    ctx.github_repo = parse_github_repo(ctx.repository) if ctx.repository else None
    ctx.releases = None  # filled by obtain_releases
    ctx.json_only = json_only
    return ctx

def repo_parse_error(ctx):
    return OrandaError(f"Your repository URL {ctx.repository} couldn't be parsed.", help_text="Only GitHub URLs are supported at the moment.")

class ReleaseData:
    def __init__(self):
        self.tag = None
        self.formatted_date = None
        self.releases = []  # list of dicts for changelog
        self.has_releases = False
        self.latest = None

def obtain_releases(ctx):
    """Fetch / determine releases. May raise fatal repo parse error."""
    ctx.releases = ReleaseData()
    if not ctx.repository:
        return
    needs = ctx.changelog_enabled or ctx.artifacts_enabled or ctx.funding_enabled
    gh = parse_github_repo(ctx.repository)
    if needs:
        # source-aware fetch
        if ctx.source_cfg == "axodotdev":
            if gh is None:
                emit_warning_diag(repo_parse_error(ctx))
                return
            owner = gh[0]
            name_q = urllib.parse.quote(str(ctx.project_name), safe="")
            url = f"https://releases.axo.dev/github/{owner}/{name_q}/releases"
            try:
                data = fetch_url_bytes(url)
                _parse_releases_response(ctx, data)
            except FetchFailure as e:
                msg = f"couldn't get releases for github/{owner}/{ctx.project_name}"
                err = OrandaError(msg, causes=e.causes)
                emit_warning_diag(err)
            return
        else:
            if gh is None:
                emit_warning_diag(repo_parse_error(ctx))
                return
            owner, repo = gh
            proxy_url = f"https://octolotl.axodotdev.host/releases/{owner}/{repo}"
            direct_url = f"https://api.github.com/repos/{owner}/{repo}/releases"
            try:
                data = fetch_with_proxy(proxy_url, direct_url)
                _parse_releases_response(ctx, data)
            except FetchFailure as e:
                err = OrandaError("Failed fetching releases from Github.", causes=e.causes)
                emit_warning_diag(err)
            return
    else:
        # preliminary check (github only)
        if gh is None:
            # fatal
            raise repo_parse_error(ctx)
        owner, repo = gh
        proxy_url = f"https://octolotl.axodotdev.host/releases/{owner}/{repo}"
        direct_url = f"https://api.github.com/repos/{owner}/{repo}/releases"
        try:
            data = fetch_with_proxy(proxy_url, direct_url)
            _parse_releases_response(ctx, data)
        except FetchFailure as e:
            emit_simple_warning(f"Failed checking for Github releases for repo, ({owner}/{repo}). Proceeding without releases...")
        return

def _parse_releases_response(ctx, data):
    # data is JSON array from GitHub or axo service
    try:
        arr = json.loads(data.decode("utf-8"))
    except Exception:
        return
    if isinstance(arr, dict) and "releases" in arr:
        arr = arr["releases"]
    if not isinstance(arr, list):
        return
    releases = []
    for item in arr:
        if not isinstance(item, dict):
            continue
        if item.get("draft"):
            continue
        releases.append(item)
    ctx.releases.releases = releases
    ctx.releases.has_releases = bool(releases)
    if releases:
        ctx.releases.latest = releases[0]
        ctx.releases.tag = releases[0].get("tag_name") or releases[0].get("tag")
        # formatted date
        date_str = releases[0].get("published_at") or releases[0].get("created_at")
        ctx.releases.formatted_date = format_release_date(date_str)

def format_release_date(date_str):
    if not date_str:
        return None
    # GitHub: 2023-01-15T... -> "January 15, 2023" (?) approximate
    try:
        dt = datetime.datetime.fromisoformat(date_str.replace("Z","+00:00"))
        return dt.strftime("%B %d, %Y")
    except Exception:
        return date_str

