def _escape_html(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def _span(style_name, text):
    if text == "":
        return ""
    if style_name == "keyword":
        return f'<span style="font-style:italic;color:#c792ea;">{_escape_html(text)}</span>'
    if style_name == "comment":
        return f'<span style="font-style:italic;color:#546e7a;">{_escape_html(text)}</span>'
    if style_name == "attr":
        return f'<span style="font-style:italic;color:#ffcb6b;">{_escape_html(text)}</span>'
    color = SYNTAX_COLORS.get(style_name, "#eeffff")
    return f'<span style="color:{color};">{_escape_html(text)}</span>'

def _merge_tokens(tokens):
    # tokens: list of (style, text)
    merged = []
    for style, text in tokens:
        if not text:
            continue
        if merged and merged[-1][0] == style:
            merged[-1] = (style, merged[-1][1] + text)
        else:
            merged.append((style, text))
    return "".join(_span(style, text) for style, text in merged)

