        if c.isalnum() or c in "_":
            # email autolink
            m=re.match(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", text[i:])
            # only if preceding not part of something? autolink extension would link emails in text; comrak example linked test@example.com after space
            if m and (i==0 or not text[i-1].isalnum()):
                email=m.group(0)
                out.append(f'<a href="mailto:{email}" rel="noopener noreferrer">{email}</a>'); i+=len(email); continue
        # plain char (consume run of ordinary chars)
        j=i+1
        # stop at special starters
        out.append(_md_escape_text(c)); i+=1; continue
    return "".join(out)

def _find_em_end(text, start, delim):
    # find closing delim not escaped; simple
    idx=text.find(delim, start)
    if idx==-1: return -1
    if idx==start: return -1
    # content may not start/end with space for * rules? keep simple
    return idx

def _parse_link(text, i, mdctx, image=False):
    # text[i]=='['; find matching ]
    depth=0; j=i
    while j < len(text):
        if text[j]=="\\" : j+=2; continue
        if text[j]=="[" : depth+=1
        if text[j]=="]":
            depth-=1
            if depth==0: break
        j+=1
    if j>=len(text): return None
    label=text[i+1:j]
    after=j+1
    url=None; title=None
    if after < len(text) and text[after]=="(":
        # parse destination
        k=after+1
        # skip spaces
        while k<len(text) and text[k] in " \t\n": k+=1
        if k<len(text) and text[k]=="<":
            e=text.find(">",k)
            if e==-1: return None
            url=text[k+1:e]; k=e+1
        else:
            s=k; par=0
            while k<len(text):
                if text[k]=="\\" : k+=2; continue
                if text[k]=="(" : par+=1
                if text[k]==")":
                    if par==0: break
                    par-=1
                if text[k] in " \t\n" and par==0: break
                k+=1
            url=text[s:k]
        while k<len(text) and text[k] in " \t\n": k+=1
        if k<len(text) and text[k] in "\"'":
            q=text[k]; e=text.find(q,k+1)
            if e==-1: return None
            title=text[k+1:e]; k=e+1
            while k<len(text) and text[k] in " \t\n": k+=1
        elif k<len(text) and text[k]=="(":
            e=text.find(")",k+1)
            if e==-1: return None
            title=text[k+1:e]; k=e+1
            while k<len(text) and text[k] in " \t\n": k+=1
        if k>=len(text) or text[k]!=")": return None
        after=k+1
    elif after < len(text) and text[after]=="[":
        # reference
        e=text.find("]",after)
        if e==-1: return None
        ref=text[after+1:e]
        if ref=="": ref=label
        key=ref.strip().lower()
        if key not in mdctx.ref_links: return None
        url,title=mdctx.ref_links[key]; after=e+1
    else:
        # shortcut reference
        key=label.strip().lower()
        if key in mdctx.ref_links:
            url,title=mdctx.ref_links[key]
        else:
            return None
    if image:
        alt=label
        # alt is plain text (strip formatting?) comrak uses alt text content
        alt_plain=re.sub(r"[*_`]+","",alt)
        attrs=f'src="{html_lib.escape(url or "",quote=True)}" alt="{html_lib.escape(alt_plain,quote=True)}"'
        if title: attrs+=f' title="{html_lib.escape(title,quote=True)}"'
        return f"<img {attrs}>", after
    else:
        attrs=f'href="{html_lib.escape(url or "",quote=True)}"'
        if title: attrs+=f' title="{html_lib.escape(title,quote=True)}"'
        attrs+=' rel="noopener noreferrer"'
        return f"<a {attrs}>{render_inline(label, mdctx)}</a>", after

def render_markdown(md_text, site_ctx=None):
    mdctx = MDContext(site_ctx)
    if md_text is None:
        return ""
    # lines
    text = md_text.replace("\r\n","\n").replace("\r","\n")
    lines = text.split("\n")
    # Collect reference link definitions and footnote definitions (they can be anywhere, typically block level)
    # We'll pre-scan for link refs (lines matching [label]: url "title") and footnote defs,
    # but footnote defs may be multiline; comrak handles - we do simple single/multi para below in main parse by removing footnote def blocks.
    # First pass: extract footnote definitions and ref defs from raw lines, removing them from flow except footnotes rendered at end.
    # Process in block parser: it will skip ref defs and collect footnote defs.
    html_blocks, footnotes = _parse_blocks(lines, mdctx, site_ctx)
    main_html = "".join(html_blocks)
    if footnotes:
        # footnotes: list of (num, id, rendered_inner_html_of_first_para etc) - _parse_blocks already collected into mdctx
        items=[]
        for num, fid, inner in mdctx.footnotes:
            # inner is html paragraphs; comrak: <li id="fn-1">\n<p>text <a ...>↩</a></p>\n</li>\n
            # inner paragraphs: strip outer <p> wrapping manipulation: they keep <p> inside li
            content = inner.strip("\n")
            # insert backref at end of last </p>
            backref = f'<a href="#fnref-{num}" class="footnote-backref" rel="noopener noreferrer">\u21a9</a>'
            if content.endswith("</p>"):
                content = content[:-4] + " " + backref + "</p>"
            else:
                content = content + " " + backref
            items.append(f'<li id="fn-{num}">\n<p>{content[3:-4] if content.startswith("<p>") and content.endswith("</p>") else content}</p>\n</li>\n' if False else f'<li id="fn-{num}">\n{content}\n</li>\n')
            # The above construction: if content already includes <p>...</p>, use as is (with backref inserted before </p>)
        fn_html = "\n<ol>\n" + "".join(items) + "</ol>\n"
        # comrak places footnotes after main content, with a ??? look at earlier: after paragraphs, blank line then <ol>
        main_html = main_html + fn_html
    # sanitize (except our highlighted code spans/pre styles) - sanitizer preserves pre style and span styles as configured
    main_html = sanitize_html(main_html)
    return main_html

