# --------------------------------------------------------------- HTTP server (serve/dev)

MIME_TYPES = {
    ".html":"text/html",".htm":"text/html",".css":"text/css",".js":"text/javascript",".mjs":"text/javascript",".json":"application/json",".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".gif":"image/gif",".svg":"image/svg+xml",".ico":"image/x-icon",".txt":"text/plain",".xml":"application/xml",".rss":"application/rss+xml",".md":"text/markdown",".woff":"font/woff",".woff2":"font/woff2",".ttf":"font/ttf",".eot":"application/vnd.ms-fontobject",".otf":"font/otf",".wasm":"application/wasm",".pdf":"application/pdf",".zip":"application/zip",".gz":"application/gzip",".tar":"application/x-tar",".mp3":"audio/mpeg",".mp4":"video/mp4",".webm":"video/webm",".webp":"image/webp",".avif":"image/avif",".csv":"text/csv",".sh":"application/x-sh",
