LIVERELOAD_SCRIPT = """<script type="module">
  var unloaded = false;

  addEventListener('beforeunload', (event) => {
    unloaded = true;
  });

  const retry = (url) =>
    fetch(url, { cache: "no-store" })
      .then(() => console.log("[tower-livereload] reload..."))
      .then(() => window.location.reload())
      .catch(() => setTimeout(() => retry(url), 1000));

  const main = () =>
    fetch("/tower-livereload/long-name-to-avoid-collisions/long-poll", { cache: "no-store" })
      .then((rsp) => rsp.text())
      .catch(() => null)
      .then(() => console.log("[tower-livereload] disconnected..."))
      .then(() => unloaded ? null : retry("/tower-livereload/long-name-to-avoid-collisions/back-up"));

  console.log("[tower-livereload] connected...");
  main();
</script>
"""

class ReloadState:
    def __init__(self):
        self.gen=0
        import threading
        self.cond=threading.Condition()
    def trigger(self):
        with self.cond:
            self.gen+=1
            self.cond.notify_all()
    def wait_next(self, current_timeout=3600):
        with self.cond:
            cur=self.gen
            self.cond.wait_for(lambda: self.gen!=cur, timeout=current_timeout)
            return self.gen

def _http_date(ts=None):
    if ts is None: ts=time.time()
    return datetime.datetime.utcfromtimestamp(ts).strftime("%a, %d %b %Y %H:%M:%S GMT")

def serve_dir_once(conn, dist_dir, livereload=False, reload_state=None):
    # returns False if connection closed
    data=b""
    try:
        conn.settimeout(5)
        # read until headers end
        while b"\r\n\r\n" not in data and len(data) < 65536:
            chunk=conn.recv(4096)
            if not chunk:
                return False
            data+=chunk
    except Exception:
        return False
    header_end=data.find(b"\r\n\r\n")
    head=data[:header_end].decode("iso-8859-1", errors="replace")
    lines=head.split("\r\n")
    if not lines: return False
    parts=lines[0].split(" ")
    if len(parts)<2:
        return False
    method=parts[0]; raw_target=parts[1]
    headers={}
    for line in lines[1:]:
        if ":" in line:
            k,v=line.split(":",1); headers[k.strip().lower()]=v.strip()
    # content length body (ignore)
    def send_response(status, status_text, header_list, body=b""):
        hdrs="".join(f"{k}: {v}\r\n" for k,v in header_list)
        resp=f"HTTP/1.1 {status} {status_text}\r\n{hdrs}\r\n".encode("iso-8859-1")
        try:
            conn.sendall(resp + (body if method != "HEAD" else b""))
        except Exception:
            pass
    now_date=_http_date()
    # livereload endpoints
    if livereload and raw_target.startswith("/tower-livereload/long-name-to-avoid-collisions/"):
        if raw_target.endswith("/long-poll"):
            if reload_state:
                # wait for a reload; if timeout, just respond
                starting=reload_state.gen
                # Use a blocking wait in this thread
