def run_file_server(dist_dir, port, livereload=False, reload_state=None, stop_after_start_error=False):
    import threading
    # Bind
    srv=socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        srv.bind(("127.0.0.1", port))
    except OSError as e:
        srv.close()
        raise
