    t.start()
    # watch loop
    # snapshot
    def snapshot(cands):
        snap={}
        for c in cands:
            # dedup by absolute path
            key=os.path.abspath(c)
            try:
                st=os.stat(c)
                snap[key]=(st.st_mtime_ns, st.st_size)
            except OSError:
                snap[key]=None
        return snap
    watched_existing_paths=[]
    seen_keys=set()
    for c in existing:
        k=os.path.abspath(c)
        if k not in seen_keys:
            watched_existing_paths.append(c); seen_keys.add(k)
    prev=snapshot(watched_existing_paths)
    try:
        while True:
            time.sleep(0.25)
            cur=snapshot(watched_existing_paths)
            changed=[]
            for k in prev:
                if prev[k]!=cur[k] and cur[k] is not None:
                    changed.append(k)
            if changed:
                # debounce a bit: collect more changes for 100ms
                time.sleep(0.1)
                cur2=snapshot(watched_existing_paths)
                for k in prev:
                    if k not in changed and prev[k]!=cur2[k] and cur2[k] is not None:
                        changed.append(k)
                cur=cur2
                prev=cur
                # message: Path(s) ["...", ...] changed, rebuilding...
                formatted="["+", ".join(f'"{p}"' for p in changed)+"]"
                info(f"Path(s) {formatted} changed, rebuilding...")
                # rebuild; errors are graphical only
                old_format=OUTPUT_FORMAT
                try:
                    build_site(config_path_arg=config_path, project_root=project_root, json_only=False)
                    if reload_state: reload_state.trigger()
                except OrandaError as e:
                    _stderr_write(e.render())
                except PanicError as e:
                    _stderr_write(e.render())
                except SystemExit:
                    pass
                except Exception as e:
                    err=OrandaError(str(e))
                    _stderr_write(err.render())
                # update snapshot after rebuild (build may have touched dist but not watched source)
                prev=snapshot(watched_existing_paths)
            else:
                prev=cur
    except KeyboardInterrupt:
        return 0
    return 0

def dispatch_command(path, parsed):
    # parsed values already applied to globals in main()
    if path== "config-schema":
        return command_config_schema(parsed)
    if path=="generate-css":
        return command_generate_css(parsed)
    if path=="generate ci":
        return command_generate_ci(parsed)
    if path=="build":
        build_site(config_path_arg=parsed.get("config_path"), project_root=parsed.get("project_root"), json_only=bool(parsed.get("json_only", False)))
        return 0
    if path=="serve":
        return command_serve(parsed)
    if path=="dev":
        return command_dev(parsed)
    # should not happen
    _stderr_write(f"unimplemented command {path}\n")
    return 255

