    def is_cons(w, i):
        ch=w[i]
        if ch in "aeiou": return False
        if ch=="y":
            if i==0: return True
            return not is_cons(w,i-1)
        return True
    def m_of(w):
        n=0; i=0
        while i < len(w) and is_cons(w,i): i+=1
        while i < len(w):
            while i < len(w) and not is_cons(w,i): i+=1
            if i>=len(w): break
            n+=1
            while i < len(w) and is_cons(w,i): i+=1
        return n
    def has_vowel(w):
        return any(not is_cons(w,i) for i in range(len(w)))
    def ends_double_cons(w):
        return len(w)>=2 and w[-1]==w[-2] and is_cons(w,len(w)-1)
    def ends_cvc(w):
        if len(w)<3: return False
        return is_cons(w,len(w)-3) and not is_cons(w,len(w)-2) and is_cons(w,len(w)-1) and w[-1] not in "wxy"
